import type { HerdrLabelContract, SessionFeed, IpcDescriptor, SessionIpcRequest } from '../../src/contracts.js';
export interface AgentTerminal { address: string; parent: string | null; state: 'live' | 'finished'; status: string | { state: string } | null; labels: Readonly<Record<string, string>>; name?: string | null; program?: { name?: string; icon?: string; tint?: boolean }; template?: string | null; exitCode?: number | null; finishedAt?: number | null; reason?: string | null; signal?: number | null; exit_code?: number | null; finished_ms?: number | null }
export interface ChildRow { key: string; kind: 'remote' | 'subagent' | 'console' | 'native'; address: string | null; originalAddress: string | null; name: string; description: string | null; status: string; outcome: string | null; completeness: 'unknown' | 'complete'; finishedAt: number | null; retained: boolean; depth: number; parentKey: string | null; machine: string | null; terminal: AgentTerminal | null; action: { kind: 'peek'; terminal: string } | { kind: 'ipc'; descriptor: IpcDescriptor; request: SessionIpcRequest } | null }
export interface AgentChildIndex { readonly terminals: readonly AgentTerminal[]; readonly feeds: readonly SessionFeed[]; readonly labelContract: HerdrLabelContract }
export function indexAgentChildren(terminals: readonly AgentTerminal[], feeds: readonly SessionFeed[], labelContract: HerdrLabelContract): AgentChildIndex;
export function projectAgentChildren(terminals: readonly AgentTerminal[], feeds: readonly SessionFeed[], ownerAddress: string, labelContract: HerdrLabelContract, options?: { now?: number; completedHours?: number; completedRows?: number; machines?: readonly { name: string; layout: 'loading' | 'ready' | 'unavailable' }[]; index?: AgentChildIndex; finishedSummary?: { hiddenFinished?: number }; folded?: ReadonlySet<string>; expandedConsoles?: ReadonlySet<string> }): ChildRow[];
export interface AgentFeedPorts { listSessionIds(root: string): Promise<readonly string[]>; readTextFile(path: string): Promise<string | null>; parseFeed(text: string): SessionFeed | null }
export function loadAgentFeeds(root: string, ports: AgentFeedPorts): Promise<{ feeds: SessionFeed[]; errors: string[]; truncated: boolean }>;
export function filterTopLevelAgents<T extends { address: string }>(agents: readonly T[], terminals: readonly AgentTerminal[], contract: HerdrLabelContract): T[];
export function selectAgentChildren(rows: readonly ChildRow[], expandedConsoles?: readonly string[]): ChildRow[];
export type AgentRenderInputKind = 'agents' | 'terminals' | 'panes' | 'spaces' | 'machines' | 'feeds';
export function agentRenderInputs(input: Record<AgentRenderInputKind, unknown>, rejected: (kind: string) => void): Record<AgentRenderInputKind, Record<string, unknown>[]>;
export function agentChildRows(rows: unknown, rejected: (kind: string) => void): (Record<string, unknown> & Pick<ChildRow, 'key' | 'name' | 'kind' | 'depth'>)[];
export function agentModelInputKey(input: Record<AgentRenderInputKind, unknown> & { focus: unknown; connections: unknown; error: unknown; completedRows: number; feedStamps?: ReadonlyMap<string, string> | null; diagnostics?: unknown; contract?: unknown; configuredMachines?: unknown }, now: number, completedHours: number, feedCache?: Map<string, unknown>): string | null;
export function agentModelRowKey(rows: readonly ChildRow[]): string | null;
export function agentModelOutputKey(model: { snapshot: unknown; list: unknown; rows: ReadonlyMap<string, readonly ChildRow[]>; hiddenFinished?: ReadonlyMap<string, number>; parked: unknown; layouts: unknown; diagnostics: ReadonlySet<string>; connections: unknown; error: unknown; contract: HerdrLabelContract }): string | null;
export function agentModelChildStats(rows: readonly ChildRow[], listed: ReadonlyMap<string, string>, ranks: Readonly<Record<string, number>>): { consoles: ChildRow[]; bots: ChildRow[]; states: string[]; rank: number };
export function agentModelTreeStates(model: { childOwners: ReadonlyMap<string, ReadonlySet<string>>; groupOwners: ReadonlyMap<string, ReadonlySet<string>> }, folded: ReadonlySet<string>, expandedConsoles: ReadonlySet<string>, expandedGroups: ReadonlySet<string>, shownFinished: ReadonlySet<string>): Map<string, string>;
